class CrossCheck(unittest.TestCase):
    def test_matches_stdlib_isocalendar_over_1600_to_2400(self):
        d = datetime.date(1600, 1, 1)
        end = datetime.date(2400, 12, 31)
        n = 0
        while d <= end:
            iy, iw, iwd = d.isocalendar()
            self.assertEqual(iso_week(d.year, d.month, d.day), (iy, iw, iwd), str(d))
            n += 1
            d += datetime.timedelta(days=1)
        self.assertGreater(n, 290000)

    def test_from_iso_inverts_iso_week_over_range(self):
        d = datetime.date(1600, 1, 1)
        end = datetime.date(2400, 12, 31)
        while d <= end:
            y, w, wd = iso_week(d.year, d.month, d.day)
            self.assertEqual(from_iso(y, w, wd), (d.year, d.month, d.day), str(d))
            d += datetime.timedelta(days=1)

    def test_from_iso_rejects_every_missing_week53(self):
        for y in range(1600, 2401):
            has53 = datetime.date(y, 12, 28).isocalendar()[1] == 53
            if not has53:
                with self.assertRaises(ValueError, msg=str(y)):
                    from_iso(y, 53, 1)


